@import '../../utils/forced-colors.css';

:host {
  display: block;
  min-width: 0;
}

.agent-tool {
  min-width: 0;
  color: var(--color-foreground-secondary);
}

details {
  margin: 0;
}

summary,
.agent-tool__row {
  min-width: 0;
  padding: var(--dimension-space-050) 0;
}

summary {
  cursor: pointer;
  list-style: none;
}

summary::-webkit-details-marker {
  display: none;
}

.agent-tool__summary-content {
  display: grid;
  align-items: center;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--dimension-space-075);
  min-width: 0;
}

.agent-tool__status-icon {
  display: flex;
  align-items: center;
  color: var(--color-foreground-faint-neutral);
}

.agent-tool--preparing .agent-tool__status-icon,
.agent-tool--queued .agent-tool__status-icon,
.agent-tool--running .agent-tool__status-icon {
  color: var(--color-foreground-faint-brand);
}

.agent-tool--waiting-for-user .agent-tool__status-icon {
  color: var(--color-foreground-bold-warning);
}

.agent-tool--error .agent-tool__status-icon,
.agent-tool--denied .agent-tool__status-icon {
  color: var(--color-foreground-bold-negative);
}

.agent-tool__title {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--dimension-space-025) var(--dimension-space-075);
  min-width: 0;
  overflow-wrap: anywhere;
}

.agent-tool__chevron {
  transition: none;
}

details[open] .agent-tool__chevron {
  transform: rotate(90deg);
}

.agent-tool__details,
.agent-tool__diagnostics {
  display: grid;
  gap: var(--dimension-space-075);
}

.agent-tool__details {
  padding: var(--dimension-space-050) 0 var(--dimension-space-100)
    calc(var(--dimension-size-200) + var(--dimension-space-075));
}

.agent-tool__diagnostics section {
  display: grid;
  gap: var(--dimension-space-025);
}

pre {
  max-width: 100%;
  margin: 0;
  padding: var(--dimension-space-075);
  overflow: auto;
  border-radius: var(--dimension-radius-050);
  background: var(--color-background-secondary);
  color: var(--color-foreground-primary);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.agent-tool__result {
  min-width: 0;
  padding-block: var(--dimension-space-050);
}

summary:focus-visible {
  border-radius: var(--dimension-radius-025);
  outline: var(--dimension-stroke-width-025) solid var(--color-border-bold-brand);
  outline-offset: var(--dimension-space-025);
}

@media (prefers-reduced-motion: no-preference) {
  .agent-tool__chevron {
    transition: transform var(--effect-motion-short-2);
  }
}

@media (forced-colors: active) {
  summary:focus-visible {
    outline-color: var(--ds-forced-color-selected);
  }

  .agent-tool--error .agent-tool__summary-content,
  .agent-tool--denied .agent-tool__summary-content {
    border-inline-start: var(--dimension-stroke-width-025) solid
      var(--ds-forced-color-content);
    padding-inline-start: var(--dimension-space-050);
  }
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
} from '@stencil/core';
import type { AgentToolState } from '../conversation-types';

const STATUS_LABELS: Record<AgentToolState, string> = {
  preparing: 'Preparing',
  queued: 'Queued',
  running: 'Running',
  'waiting-for-user': 'Waiting for your response',
  success: 'Completed',
  error: 'Failed',
  denied: 'Permission denied',
  canceled: 'Canceled',
};

@Component({ tag: 'ds-agent-tool-call', styleUrl: 'AgentToolCall.css', scoped: true })
export class AgentToolCall {
  @Element() el!: HTMLElement;

  @Prop() name: string = '';
  @Prop() label: string = '';
  @Prop() state: AgentToolState = 'queued';
  @Prop() statusLabel?: string;
  @Prop() input?: unknown;
  @Prop() output?: unknown;
  @Prop() error?: string;
  @Prop() open: boolean = false;

  @Event() dsOpenChange!: EventEmitter<{ open: boolean }>;

  @State() private hasSummary = false;
  @State() private hasResult = false;
  @State() private hasDetails = false;

  private slotObserver?: MutationObserver;

  componentWillLoad() {
    this.syncSlots();
  }

  componentDidLoad() {
    this.syncSlots();
    this.slotObserver = new MutationObserver(() => this.syncSlots());
    this.slotObserver.observe(this.el, {
      childList: true,
      subtree: false,
      attributes: true,
      attributeFilter: ['slot'],
    });
  }

  disconnectedCallback() {
    this.slotObserver?.disconnect();
  }

  private syncSlots() {
    this.hasSummary = Boolean(this.el.querySelector('[slot="summary"]'));
    this.hasResult = Boolean(this.el.querySelector('[slot="result"]'));
    this.hasDetails = Boolean(this.el.querySelector('[slot="details"]'));
  }

  private serialize(value: unknown) {
    if (value === undefined) return '';
    if (typeof value === 'string') return value;
    try {
      return JSON.stringify(value, null, 2);
    } catch {
      return String(value);
    }
  }

  private get active(): boolean {
    return ['preparing', 'queued', 'running'].includes(this.state);
  }

  private get expandable(): boolean {
    return (
      this.hasDetails ||
      this.input !== undefined ||
      this.output !== undefined ||
      Boolean(this.error)
    );
  }

  private renderStatusIcon() {
    if (this.active) return <ds-loader size="xs" color="inherit" />;
    if (this.state === 'success') {
      return <ds-icon name="Check" size="xs" color="inherit" />;
    }
    if (this.state === 'waiting-for-user') {
      return <ds-icon name="Clock" size="xs" color="inherit" />;
    }
    return <ds-icon name="ErrorTriangle" size="xs" color="inherit" />;
  }

  private renderSummary(expandable: boolean) {
    return (
      <span class="agent-tool__summary-content">
        <span class="agent-tool__status-icon" aria-hidden="true">
          {this.renderStatusIcon()}
        </span>
        <span class="agent-tool__title">
          {this.hasSummary ? (
            <slot name="summary" />
          ) : (
            <ds-text as="span" variant="text-body-small" emphasis>
              {this.label || this.name}
            </ds-text>
          )}
          <ds-text
            class="agent-tool__state-label"
            as="span"
            variant="text-caption"
            color={['error', 'denied'].includes(this.state) ? 'negative' : 'secondary'}
          >
            {this.statusLabel ?? STATUS_LABELS[this.state]}
          </ds-text>
        </span>
        {expandable ? (
          <ds-icon
            class="agent-tool__chevron"
            name="ChevronRight"
            size="xs"
            color="inherit"
          />
        ) : null}
      </span>
    );
  }

  private renderGenericDetails() {
    return (
      <div class="agent-tool__diagnostics">
        {this.input !== undefined ? (
          <section>
            <ds-text variant="text-caption" emphasis>Input</ds-text>
            <pre>{this.serialize(this.input)}</pre>
          </section>
        ) : null}
        {this.output !== undefined ? (
          <section>
            <ds-text variant="text-caption" emphasis>Output</ds-text>
            <pre>{this.serialize(this.output)}</pre>
          </section>
        ) : null}
        {this.error ? (
          <section>
            <ds-text variant="text-caption" emphasis>Error</ds-text>
            <pre>{this.error}</pre>
          </section>
        ) : null}
      </div>
    );
  }

  private handleToggle = (event: Event) => {
    this.dsOpenChange.emit({ open: (event.currentTarget as HTMLDetailsElement).open });
  };

  render() {
    const expandable = this.expandable;
    return (
      <Host>
        <div class={`agent-tool agent-tool--${this.state}`}>
          {expandable ? (
            <details open={this.open} onToggle={this.handleToggle}>
              <summary>{this.renderSummary(true)}</summary>
              <div class="agent-tool__details">
                {this.hasDetails ? <slot name="details" /> : this.renderGenericDetails()}
              </div>
            </details>
          ) : (
            <div class="agent-tool__row">{this.renderSummary(false)}</div>
          )}
          {this.hasResult ? (
            <div class="agent-tool__result">
              <slot name="result" />
            </div>
          ) : null}
        </div>
      </Host>
    );
  }
}
